function blend(palette,value,min,max){if(!valid(value))return '#aeb9bb';const p=Math.max(0,Math.min(1,(Number(value)-min)/(max-min)))*(palette.length-1),i=Math.min(palette.length-2,Math.floor(p)),f=p-i;const a=palette[i].match(/\w\w/g).map(x=>parseInt(x,16)),b=palette[i+1].match(/\w\w/g).map(x=>parseInt(x,16));return '#'+a.map((v,j)=>Math.round(v+(b[j]-v)*f).toString(16).padStart(2,'0')).join('');}
