function multiRecord(p){const ms=metrics[state.metric];const entries=[[T('Source ID','Kaynak kimliği'),p.asset_id],[T('Infrastructure category','Altyapı türü'),B(sector[p.category])||p.category],[T('Scope','Kapsam'),p.scope==='Alanya'?'Alanya':T('External airport corridor','Harici havalimanı koridoru')]];
 if(state.module!=='inventory')entries.push([B(ms.label),F(p[state.metric],2)+' '+unitOf(ms)]);
 if(valid(p.length_m))entries.push([T('Source centreline length','Kaynak yol ekseni uzunluğu'),F(p.length_m,1)+' m']);
 entries.push([T('Summer surface temperature','Yaz yüzey sıcaklığı'),F(p.lst_median,2)+' °C'],[T('Thermal pixel coverage','Termal piksel kapsamı'),F(valid(p.lst_valid_fraction)?p.lst_valid_fraction*100:null,1)+'%'],[T('NDVI greenness','NDVI yeşillik indisi'),F(p.ndvi_median,3)],[T('Climate profile','İklim profili'),p.climate_cell_id||T('Unknown','Bilinmiyor')],[T('Temperature profile distance','Sıcaklık profiline uzaklık'),F(p.temperature_profile_distance_km,2)+' km'],[T('Data quality / access notes','Veri kalitesi / erişim notları'),qualityNotes(p.qa_flags)]);return entries;}
function qualityNotes(flags){if(!flags)return T('No additional source flag','Ek kaynak bayrağı yok');const q={low_thermal_pixel_coverage:bi('Low thermal pixel coverage (<50%)','Düşük termal piksel kapsamı (<%50)'),no_valid_thermal_context:bi('No valid thermal context','Geçerli termal bağlam yok'),footprint_smaller_than_thermal_grid_pixel:bi('Footprint smaller than thermal grid pixel','Tesis alanı termal pikselden küçük'),not_counted_as_confirmed_hospital:bi('Excluded from confirmed hospital count','Doğrulanmış hastane toplamına dahil değil'),coastal_temperature_land_mask_search:bi('Coastal temperature land-cell search','Kıyıda kara sıcaklık hücresi arandı'),temperature_profile_distance_above_10km:bi('Temperature profile more than 10 km away','Sıcaklık profili 10 km uzakta'),missing_air_temperature_indicator:bi('Air-temperature indicator unavailable','Hava sıcaklığı göstergesi eksik'),location_only_no_footprint:bi('Location only; no footprint','Yalnız konum; bina oturumu yok'),sports_public_access_unverified:bi('Public access unverified','Kamusal erişim doğrulanmamış'),temperature_profile_distant:bi('Distant native temperature profile','Uzak özgün sıcaklık profili'),thermal_no_valid_pixels:bi('No valid thermal pixels','Geçerli termal piksel yok')};return String(flags).split(';').map(f=>q[f]?B(q[f]):f).join(' · ');}
